import math

class Solution:
    def minimizeArrayValue(self, nums: list[int]) -> int:
        res = 0
        pref_sum = 0
        for i, x in enumerate(nums):
            pref_sum += x
            avg = math.ceil(pref_sum / (i + 1))
            if avg > res:
                res = avg
        return res

class Solution {
public:
    int minimizeArrayValue(std::vector<int>& nums) {
        long long res = 0;
        long long pref_sum = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            pref_sum += nums[i];
            long long avg = (pref_sum + i) / (i + 1);
            res = std::max(res, avg);
        }
        return res;
    }
};

class Solution {
    public int minimizeArrayValue(int[] nums) {
        long res = 0;
        long prefSum = 0;
        for (int i = 0; i < nums.length; i++) {
            prefSum += nums[i];
            long avg = (prefSum + i) / (i + 1);
            if (avg > res) res = avg;
        }
        return (int) res;
    }
}

var minimizeArrayValue = function(nums) {
    let res = 0;
    let prefSum = 0;
    for (let i = 0; i < nums.length; i++) {
        prefSum += nums[i];
        const avg = Math.ceil(prefSum / (i + 1));
        if (avg > res) res = avg;
    }
    return res;
};
